function gearPath(n,ro,ri,cx,cy,hole,ph){let d='',s=2*Math.PI/n,P=(r,a)=>[cx+r*Math.cos(a),cy+r*Math.sin(a)];
 for(let i=0;i<n;i++){const a=i*s+ph,pts=[P(ri,a-s*.3),P(ro,a-s*.17),P(ro,a+s*.17),P(ri,a+s*.3)];d+=(i?'L':'M')+pts.map(q=>q[0].toFixed(1)+' '+q[1].toFixed(1)).join('L')}
 return d+'Z M'+(cx+hole)+' '+cy+'A'+hole+' '+hole+' 0 1 0 '+(cx-hole)+' '+cy+'A'+hole+' '+hole+' 0 1 0 '+(cx+hole)+' '+cy+'Z'}
const CKT='<svg class="ckt" viewBox="0 0 1200 700" preserveAspectRatio="xMidYMid slice"><g class="tr"><path d="M0 120H220V260H480V180H760V320H1200"/><path d="M0 420H180V540H420V460H700V600H1000V520H1200"/><path d="M300 0V90H560V0"/><path d="M820 700V620H940V440H1200"/><path d="M60 700V600H260"/></g><g class="nd"><circle cx="220" cy="120" r="6"/><circle cx="480" cy="260" r="6"/><circle cx="760" cy="180" r="6"/><circle cx="760" cy="320" r="6"/><circle cx="180" cy="420" r="6"/><circle cx="420" cy="540" r="6"/><circle cx="700" cy="460" r="6"/><circle cx="1000" cy="600" r="6"/><circle cx="560" cy="90" r="6"/><circle cx="940" cy="440" r="6"/><circle cx="260" cy="600" r="6"/></g></svg>';
