const cio=new IntersectionObserver(e=>e.forEach(y=>{if(!y.isIntersecting)return;cio.unobserve(y.target);const el=y.target,m=el.textContent.match(/^([₹~]?)([\d,]+)(L?\+?)$/);
 if(!m||still||(/^\d{4}$/.test(m[2])&&+m[2]>1900))return;const n=+m[2].replace(/,/g,''),t0=performance.now();
 (function f(){const q=Math.min((performance.now()-t0)/1400,1);el.textContent=m[1]+Math.round(n*(1-Math.pow(1-q,3))).toLocaleString('en-IN')+m[3];if(q<1)requestAnimationFrame(f)})()}),{threshold:.6});
