(function(){const x=Object.values(DIVES).flat().find(v=>v.term),el=$('#term');if(!x||!el)return;const full=['$ techideate --highlights'].concat(x.h.map(h=>'> '+h)).join('\n');
 if(still){el.textContent=full;return}
 new IntersectionObserver((e,o)=>{if(e[0].isIntersecting){o.disconnect();let n=0;const t=setInterval(()=>{n++;el.textContent=full.slice(0,n);if(n>=full.length)clearInterval(t)},32)}},{threshold:.5}).observe(el)})();
